#define AES_KEYLEN 16 // Key length in bytes
#define AES_keyExpSize 176

typedef uint8_t state_t[4][4];
struct AES_ctx {
    uint8_t RoundKey[AES_keyExpSize];
};

void AddRoundKey(unsigned char, unsigned char (*)[4][4], unsigned char const *);
